def tidy_tower_custom_strategy(tower):
    operations = []
    n = len(tower)

    # Function to determine the best operation for aligning cubes
    def get_best_operation(target_cube, cube):
        if cube == target_cube:
            return [0, 0]  # No operation needed
        if cube == 'R' and target_cube == 'G':
            return [0, 1]  # Rotate once if holding, else Skip rotation
        if cube == 'G' and target_cube == 'R':
            return [0, 1]  # Rotate once if holding, else Skip rotation
        if cube == 'Y' and (target_cube == 'R' or target_cube == 'G'):
            return [0, 1]  # Rotate once if holding, else Skip rotation
        if cube == 'B' and (target_cube == 'Y' or target_cube == 'G'):
            return [0, 1]  # Rotate once if holding, else Skip rotation
        if cube == 'Y' and target_cube == 'B':
            return [0, 1]  # Rotate once if holding, else Skip rotation
        if cube == 'G' and target_cube == 'B':
            return [0, 1]  # Rotate once if holding, else Skip rotation
        return [1, 0]  # Default no rotation

    for i in range(n - 1, -1, -1):
        # Find the target color which is common below
        target_color = tower[i + 1]
        for j in range(i + 1, n):
            target_color = ''.join(sorted(target_color + tower[j]))[j]  # Sort and get middle color
        curr_color = tower[i]
        operation = get_best_operation(target_color, curr_color)
        cube_index, rotation, hold = operation
        operations.append([cube_index, rotation, hold])
    return operations

